    case 27: /* ENGINE_ATTRIBUTE */
    case 28: /* EVERY */
    case 29: /* EXISTS */
    case 30: /* EXPORT */
    case 31: /* FILE_BLOCK_SIZE */
    case 32: /* FOLLOWS */
    case 33: /* FORCE */
    case 34: /* FOREIGN */
    case 35: /* FOUND */
    case 36: /* GROUP */
    case 37: /* GTIDS */
    case 38: /* HISTOGRAM */
    case 39: /* IDENTIFIED */
    case 40: /* INACTIVE */
    case 41: /* INFILE */
    case 42: /* INNODB */
    case 43: /* INVOKER */
    case 44: /* JOIN */
    case 45: /* KEYRING */
    case 46: /* LEAVES */
    case 47: /* MERGE */
    case 48: /* MIGRATE */
    case 49: /* MUTEX */
    case 50: /* NAME */
    case 51: /* NOT */
    case 52: /* ONE */
    case 53: /* ONLY */
    case 54: /* OPTIONS */
    case 55: /* ORGANIZATION */
    case 56: /* PARTITION */
    case 57: /* PHASE */
    case 58: /* PRECEDES */
    case 59: /* PRESERVE */
    case 60: /* REDO_LOG */
    case 61: /* REFERENCE */
    case 62: /* RELOAD */
    case 63: /* RESUME */
    case 64: /* RETURNS */
    case 65: /* ROTATE */
    case 66: /* SCHEDULE */
    case 67: /* SNAPSHOT */
    case 68: /* SONAME */
    case 69: /* SOURCE */
    case 70: /* SQL_AFTER_GTIDS */
    case 71: /* SQL_AFTER_MTS_GAPS */
    case 72: /* SQL_BEFORE_GTIDS */
    case 73: /* SUSPEND */
