      /* (1116) handler_read_suffix ::= */ yytestcase(yyruleno==1116);
      /* (1127) call_arguments ::= */ yytestcase(yyruleno==1127);
      /* (1174) flush_table_tail ::= */ yytestcase(yyruleno==1174);
      /* (1210) dml_write_column_tokens ::= */ yytestcase(yyruleno==1210);
      /* (1237) dml_write_parenthesized_query_tail ::= */ yytestcase(yyruleno==1237);
      /* (1248) dml_write_after_parenthesized_query ::= */ yytestcase(yyruleno==1248);
